30|int
31|LLVMFuzzerTestOneInput(const char *data, size_t size) {
32|    xmlParserCtxtPtr ctxt;
33|    xmlDocPtr doc;
34|    const char *docBuffer, *docUrl;
35|    size_t maxAlloc, docSize;
36|    int opts;
37|
38|    xmlFuzzDataInit(data, size);
39|    opts = (int) xmlFuzzReadInt(4);
40|    /*
41|     * Disable options that are known to cause timeouts
42|     */
43|    opts &= ~XML_PARSE_XINCLUDE &
44|            ~XML_PARSE_DTDVALID &
45|            ~XML_PARSE_SAX1;
46|    maxAlloc = xmlFuzzReadInt(4) % (size + 100);
47|
48|    xmlFuzzReadEntities();
49|    docBuffer = xmlFuzzMainEntity(&docSize);
50|    docUrl = xmlFuzzMainUrl();
51|    if (docBuffer == NULL)
52|        goto exit;
53|
54|    /* Pull parser */
55|
56|    xmlFuzzMemSetLimit(maxAlloc);
57|    ctxt = xmlNewParserCtxt();
58|    if (ctxt != NULL) {
59|        doc = xmlCtxtReadMemory(ctxt, docBuffer, docSize, docUrl, NULL, opts);
60|        xmlFuzzCheckMallocFailure("xmlCtxtReadMemory",
61|                                  ctxt->errNo == XML_ERR_NO_MEMORY);
62|
63|        if (doc != NULL) {
64|#ifdef LIBXML_OUTPUT_ENABLED
65|            xmlBufferPtr buffer;
66|            xmlSaveCtxtPtr save;
67|
68|            /* Also test the serializer. */
69|            xmlFuzzResetMallocFailed();
70|            buffer = xmlBufferCreate();
71|            save = xmlSaveToBuffer(buffer, NULL, 0);
72|            if (save != NULL) {
73|                int errNo;
74|
75|                xmlSaveDoc(save, doc);
76|                errNo = xmlSaveFinish(save);
77|                xmlFuzzCheckMallocFailure("xmlDocDumpMemory",
78|                                          errNo == XML_ERR_NO_MEMORY);
79|            }
80|            xmlBufferFree(buffer);
81|#endif
82|            xmlFreeDoc(doc);
83|        }
84|
85|        xmlFreeParserCtxt(ctxt);
86|    }
87|
88|    /* Push parser */
89|
90|#ifdef LIBXML_PUSH_ENABLED
91|    {
92|        static const size_t maxChunkSize = 128;
93|        size_t consumed, chunkSize;
94|
95|        xmlFuzzMemSetLimit(maxAlloc);
96|        ctxt = xmlCreatePushParserCtxt(NULL, NULL, NULL, 0, docUrl);
97|        if (ctxt != NULL) {
98|            xmlCtxtUseOptions(ctxt, opts);
99|
100|            for (consumed = 0; consumed < docSize; consumed += chunkSize) {
101|                chunkSize = docSize - consumed;
102|                if (chunkSize > maxChunkSize)
103|                    chunkSize = maxChunkSize;
104|                xmlParseChunk(ctxt, docBuffer + consumed, chunkSize, 0);
105|            }
106|
107|            xmlParseChunk(ctxt, NULL, 0, 1);
108|            xmlFuzzCheckMallocFailure("xmlParseChunk",
109|                                      ctxt->errNo == XML_ERR_NO_MEMORY);
110|            xmlFreeDoc(ctxt->myDoc);
111|            xmlFreeParserCtxt(ctxt);
112|        }
113|    }
114|#endif
115|
116|    /* Reader */
117|
118|#ifdef LIBXML_READER_ENABLED
119|    {
120|        xmlTextReaderPtr reader;
121|        const xmlError *error;
122|        int j;
123|
124|        xmlFuzzMemSetLimit(maxAlloc);
125|        reader = xmlReaderForMemory(docBuffer, docSize, NULL, NULL, opts);
126|        if (reader != NULL) {
127|            while (xmlTextReaderRead(reader) == 1) {
128|                if (xmlTextReaderNodeType(reader) == XML_ELEMENT_NODE) {
129|                    int i, n = xmlTextReaderAttributeCount(reader);
130|                    for (i=0; i<n; i++) {
131|                        xmlTextReaderMoveToAttributeNo(reader, i);
132|                        while (xmlTextReaderReadAttributeValue(reader) == 1);
133|                    }
134|                }
135|            }
136|            for (j = 0; j < 10; j++)
137|                xmlTextReaderRead(reader);
138|            error = xmlTextReaderGetLastError(reader);
139|            xmlFuzzCheckMallocFailure("xmlTextReaderRead",
140|                                      error->code == XML_ERR_NO_MEMORY);
141|            xmlFreeTextReader(reader);
142|        }
143|    }
144|#endif
145|
146|exit:
147|    xmlFuzzMemSetLimit(0);
148|    xmlFuzzDataCleanup();
149|    xmlResetLastError();
150|    return(0);
151|}
