271|void
272|xmlSAX2ExternalSubset(void *ctx, const xmlChar *name,
273|	       const xmlChar *ExternalID, const xmlChar *SystemID)
274|{
275|    xmlParserCtxtPtr ctxt = (xmlParserCtxtPtr) ctx;
276|    if (ctx == NULL) return;
277|    if (((ExternalID != NULL) || (SystemID != NULL)) &&
278|        (((ctxt->validate) || (ctxt->loadsubset != 0)) &&
279|	 (ctxt->wellFormed && ctxt->myDoc))) {
280|	/*
281|	 * Try to fetch and parse the external subset.
282|	 */
283|	xmlParserInputPtr oldinput;
284|	int oldinputNr;
285|	int oldinputMax;
286|	xmlParserInputPtr *oldinputTab;
287|	xmlParserInputPtr input = NULL;
288|	const xmlChar *oldencoding;
289|        unsigned long consumed;
290|        size_t buffered;
291|
292|	/*
293|	 * Ask the Entity resolver to load the damn thing
294|	 */
295|	if ((ctxt->sax != NULL) && (ctxt->sax->resolveEntity != NULL))
296|	    input = ctxt->sax->resolveEntity(ctxt->userData, ExternalID,
297|	                                        SystemID);
298|	if (input == NULL) {
299|	    return;
300|	}
301|
302|	if (xmlNewDtd(ctxt->myDoc, name, ExternalID, SystemID) == NULL) {
303|            xmlSAX2ErrMemory(ctxt);
304|            xmlFreeInputStream(input);
305|            return;
306|        }
307|
308|	/*
309|	 * make sure we won't destroy the main document context
310|	 */
311|	oldinput = ctxt->input;
312|	oldinputNr = ctxt->inputNr;
313|	oldinputMax = ctxt->inputMax;
314|	oldinputTab = ctxt->inputTab;
315|	oldencoding = ctxt->encoding;
316|	ctxt->encoding = NULL;
317|
318|	ctxt->inputTab = (xmlParserInputPtr *)
319|	                 xmlMalloc(5 * sizeof(xmlParserInputPtr));
320|	if (ctxt->inputTab == NULL) {
321|	    xmlSAX2ErrMemory(ctxt);
322|            xmlFreeInputStream(input);
323|	    ctxt->input = oldinput;
324|	    ctxt->inputNr = oldinputNr;
325|	    ctxt->inputMax = oldinputMax;
326|	    ctxt->inputTab = oldinputTab;
327|	    ctxt->encoding = oldencoding;
328|	    return;
329|	}
330|	ctxt->inputNr = 0;
331|	ctxt->inputMax = 5;
332|	ctxt->input = NULL;
333|	xmlPushInput(ctxt, input);
334|
335|	if (input->filename == NULL)
336|	    input->filename = (char *) xmlCanonicPath(SystemID);
337|	input->line = 1;
338|	input->col = 1;
339|	input->base = ctxt->input->cur;
340|	input->cur = ctxt->input->cur;
341|	input->free = NULL;
342|
343|	/*
344|	 * let's parse that entity knowing it's an external subset.
345|	 */
346|	xmlParseExternalSubset(ctxt, ExternalID, SystemID);
347|
348|        /*
349|	 * Free up the external entities
350|	 */
351|
352|	while (ctxt->inputNr > 1)
353|	    xmlPopInput(ctxt);
354|
355|        consumed = ctxt->input->consumed;
356|        buffered = ctxt->input->cur - ctxt->input->base;
357|        if (buffered > ULONG_MAX - consumed)
358|            consumed = ULONG_MAX;
359|        else
360|            consumed += buffered;
361|        if (consumed > ULONG_MAX - ctxt->sizeentities)
362|            ctxt->sizeentities = ULONG_MAX;
363|        else
364|            ctxt->sizeentities += consumed;
365|
366|	xmlFreeInputStream(ctxt->input);
367|        xmlFree(ctxt->inputTab);
368|
369|	/*
370|	 * Restore the parsing context of the main entity
371|	 */
372|	ctxt->input = oldinput;
373|	ctxt->inputNr = oldinputNr;
374|	ctxt->inputMax = oldinputMax;
375|	ctxt->inputTab = oldinputTab;
376|	if ((ctxt->encoding != NULL) &&
377|	    ((ctxt->dict == NULL) ||
378|	     (!xmlDictOwns(ctxt->dict, ctxt->encoding))))
379|	    xmlFree((xmlChar *) ctxt->encoding);
380|	ctxt->encoding = oldencoding;
381|	/* ctxt->wellFormed = oldwellFormed; */
382|    }
383|}

