3711|xmlExpandPEsInEntityValue(xmlParserCtxtPtr ctxt, xmlSBuf *buf,
3712|                          const xmlChar *str, int length, int depth) {
3713|    int maxDepth = (ctxt->options & XML_PARSE_HUGE) ? 40 : 20;
