3723|                       "Maximum entity nesting depth exceeded");
3724|	return;
3725|    }
3726|
3727|    end = str + length;
3728|    chunk = str;
3729|
3730|    while ((str < end) && (!PARSER_STOPPED(ctxt))) {
3731|        c = *str;
3732|
3733|        if (c >= 0x80) {
3734|            l = xmlUTF8MultibyteLen(ctxt, str,
3735|                    "invalid character in entity value\n");
3736|            if (l == 0) {
3737|                if (chunk < str)
3738|                    xmlSBufAddString(buf, chunk, str - chunk);
3739|                xmlSBufAddReplChar(buf);
3740|                str += 1;
3741|                chunk = str;
3742|            } else {
3743|                str += l;
3744|            }
