3746|            if (str[1] == '#') {
3747|                if (chunk < str)
3748|                    xmlSBufAddString(buf, chunk, str - chunk);
3749|
3750|                c = xmlParseStringCharRef(ctxt, &str);
3751|                if (c == 0)
3752|                    return;
