3769|                            "EntityValue: '&' forbidden except for entities "
3770|                            "references\n");
3771|                    xmlFree(name);
3772|                    return;
3773|                }
3774|
3775|                xmlFree(name);
3776|            }
3777|        } else if (c == '%') {
3778|            xmlEntityPtr ent;
3779|
3780|            if (chunk < str)
